import{_ as r,o as a,c as o,a0 as n}from"./chunks/framework.L_oL6aia.js";const c=JSON.parse('{"title":"Fangqi 邀请好友教程","description":"","frontmatter":{},"headers":[],"relativePath":"payment/referral.md","filePath":"payment/referral.md"}'),d={name:"payment/referral.md"};function e(s,t,g,i,l,h){return a(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="fangqi-邀请好友教程" tabindex="-1">Fangqi 邀请好友教程 <a class="header-anchor" href="#fangqi-邀请好友教程" aria-label="Permalink to &quot;Fangqi 邀请好友教程&quot;">​</a></h1><p>邀请好友注册 Fangqi，即可获得好友<strong>首次充值金额的返利佣金</strong>。佣金可用于平台消费，也可在满足条件后申请提现。</p><h2 id="一、返利比例与等级升级" tabindex="-1">一、返利比例与等级升级 <a class="header-anchor" href="#一、返利比例与等级升级" aria-label="Permalink to &quot;一、返利比例与等级升级&quot;">​</a></h2><p>平台根据推广人数、佣金收入及推广影响力，设置不同的返利等级：</p><table tabindex="0"><thead><tr><th>推广等级</th><th>升级条件</th><th>返利比例</th></tr></thead><tbody><tr><td><strong>普通推广员</strong></td><td>注册后默认获得</td><td><strong>10%</strong></td></tr><tr><td><strong>进阶推广员</strong></td><td>每月邀请 ≥ 10 人，或每月佣金 ≥ 30 元</td><td><strong>15%</strong></td></tr><tr><td><strong>核心合作者</strong></td><td>自媒体（博客、公众号、视频平台、TG 群等）粉丝 ≥ 1 万，联系客服审核</td><td><strong>20% + 永久返利</strong></td></tr><tr><td><strong>顶级合伙人</strong></td><td>月度佣金结算总额达到 8,000 元以上</td><td><strong>30% 循环返利</strong></td></tr></tbody></table><h2 id="二、累计返利奖励" tabindex="-1">二、累计返利奖励 <a class="header-anchor" href="#二、累计返利奖励" aria-label="Permalink to &quot;二、累计返利奖励&quot;">​</a></h2><p>累计返利达到指定金额，即可<strong>额外免费领取年付福利套餐</strong>，领取奖励不扣除已有佣金。</p><table tabindex="0"><thead><tr><th>累计返利金额</th><th>免费赠送套餐</th><th>套餐流量</th><th>免费时长</th></tr></thead><tbody><tr><td><strong>满 100 元</strong></td><td>套餐 1</td><td>50GB/月</td><td>1 年</td></tr><tr><td><strong>满 200 元</strong></td><td>套餐 2</td><td>70GB/月</td><td>1 年</td></tr><tr><td><strong>满 300 元</strong></td><td>套餐 3</td><td>90GB/月</td><td>1 年</td></tr></tbody></table><h2 id="三、如何获取专属邀请链接" tabindex="-1">三、如何获取专属邀请链接 <a class="header-anchor" href="#三、如何获取专属邀请链接" aria-label="Permalink to &quot;三、如何获取专属邀请链接&quot;">​</a></h2><ol><li>登录 Fangqi 用户后台。</li><li>点击左上角菜单，进入 <strong>【我的邀请】</strong>。</li><li>复制自己的<strong>专属注册链接</strong>或<strong>专属邀请码</strong>，分享给好友。</li><li>好友通过专属链接注册后，系统将自动绑定邀请关系。</li></ol><p><strong>温馨提示：</strong> 好友充值后，佣金需经过 <strong>3 天风控期</strong>，审核通过后自动确认到账。</p><h2 id="四、佣金使用与提现规则" tabindex="-1">四、佣金使用与提现规则 <a class="header-anchor" href="#四、佣金使用与提现规则" aria-label="Permalink to &quot;四、佣金使用与提现规则&quot;">​</a></h2><ul><li><strong>账户消费：</strong> 佣金可直接划转至账户余额，用于购买或续费套餐，消费无门槛。</li><li><strong>申请提现：</strong> 累计佣金满 <strong>300 元</strong> 后，可申请提现。</li><li><strong>提现方式：</strong> 统一通过 <strong>USDT（TRC-20）钱包</strong>结算。</li><li><strong>到账时间：</strong> 提交提现申请后，通常在 <strong>24 小时内</strong>到账。</li></ul><h2 id="五、开始邀请好友" tabindex="-1">五、开始邀请好友 <a class="header-anchor" href="#五、开始邀请好友" aria-label="Permalink to &quot;五、开始邀请好友&quot;">​</a></h2><p>登录 Fangqi 用户后台，进入 <strong>【我的邀请】</strong>，获取专属邀请链接并分享给好友，即可开启推广返利。</p><p>邀请越多，返利越高，还有机会领取免费年付套餐福利。</p>',16)])])}const b=r(d,[["render",e]]);export{c as __pageData,b as default};
